// === Tab: ISO ===
class ISO {
	constructor(cx, cy, scl = 10) {
		this.scl = scl;
		this.cx = cx;
		this.cy = cy;

		this.dy = 1 * scl;
		this.dx = sqrt(3) * scl;
		this.dx2 = this.dx * 0.5;
		this.dy2 = this.dy * 0.5;

		this.cubes = [];
	}

	getDim(pos) {
		let x = 0, y = 0, z = 0;
		x += pos.x * -this.dx;
		y += pos.x * this.dy2;
		x += pos.y * this.dx;
		y += pos.y * this.dy2;
		y += pos.z * -this.dy;
		z += pos.z * -this.dy;
		return { x, y, z }
	}

	getCoord(pos) {
		var x = this.cx,
			y = this.cy,
			z = 0;
		let dim = this.getDim(pos); // console.log(dim)
		return {
			x: x + dim.x,
			y: y + dim.y
		};
	}

	drawCoordSystem(n = 10) {
		for (let y = 0; y < n; y++) {
			for (let x = 0; x < n; x++) {
				const coord = this.getCoord({
					x, y, z: 0
				});
				circle(coord.x, coord.y, 1);
			}
		}
	}

	addCube(pos, dim, clr, pad = null) {
		const pts = {
			p1: 0,
			p2: 0,
			p3: 0,
			p4: 0,
			z: 0
		}; // p1..4: nesw bottom, z: dy to top;
		// const off = {}
		const posOrig = {
			x: pos.x, y: pos.y, z: pos.z
		};
		const dimOrig = {
			x: dim.x, y: dim.y, z: dim.z
		};
		const cube = {
			posOrig,
			pos,
			dimOrig,
			dim,
			clr,
			pad,
			pts,
			zOrder: 0
		};
		this.recalcCubePtsFromPadding(cube);
		this.cubes.push(cube);
		// console.log(cube.zOrder);
	}
	recalcCubePtsFromPadding(cube) {
		if (cube.pad) {
			cube.pos.x += cube.pad.x;
			cube.pos.y += cube.pad.y;
			cube.pos.z += cube.pad.z;
			cube.dim.x -= 2 * cube.pad.x
			cube.dim.y -= 2 * cube.pad.y
			cube.dim.z -= 2 * cube.pad.z
		}

		// calc points {p1..4,z}: north,east,south,west / top,right,bottom,left / z: y-off
		const dimX = this.getDim({
			x: cube.dim.x, y: 0, z: 0
		});
		const dimY = this.getDim({
			x: 0, y: cube.dim.y, z: 0
		});
		const dimZ = this.getDim({
			x: 0, y: 0, z: cube.dim.z
		});
		cube.pts.p1 = this.getCoord(cube.pos);
		cube.pts.p2 = {
			x: cube.pts.p1.x + dimY.x,
			y: cube.pts.p1.y + dimY.y
		};
		cube.pts.p3 = {
			x: cube.pts.p1.x + dimX.x + dimY.x,
			y: cube.pts.p1.y + dimX.y + dimY.y
		};
		cube.pts.p4 = {
			x: cube.pts.p1.x + dimX.x,
			y: cube.pts.p1.y + dimX.y
		};
		cube.pts.z = dimZ;

		// for ordering
		cube.zOrder = dist(cube.pts.p3.x, cube.pts.p3.y, width / 2, height * 2);
	}

	sortCubes() {
		// ToDo: http://shaunlebron.github.io/IsometricBlocks/

		// this.cubes = this.cubes.sort((a, b) => b.zOrder - a.zOrder);

		/*
		this.cubes = this.cubes.sort((a, b) => { 
			// return b.zOrder - a.zOrder
			if (a.pos.y + a.dim.y == b.pos.y + b.dim.y) {
				return (b.pos.x + b.dim.x) - (a.pos.x + a.dim.x);
			}
			return (b.pos.y + b.dim.y) - (a.pos.y + a.dim.y);
		});
		*/

		this.cubes = this.cubes.sort((a, b) => {
			return (a.pts.p1.y + a.pts.z.y) - (b.pts.p1.y + b.pts.z.y);
		});
	}

	drawCubes() {
		this.sortCubes();

		noFill();
		strokeWeight(2);
		for (const cube of this.cubes) {
			if (cube.pts.z.y !== 0) {
				// left: dark clr
				stroke(this.colorBr(cube.clr, 0.7));
				beginShape()
				vertex(cube.pts.p3.x, cube.pts.p3.y);
				vertex(cube.pts.p4.x, cube.pts.p4.y);
				vertex(cube.pts.p4.x + cube.pts.z.x, cube.pts.p4.y + cube.pts.z.y);
				vertex(cube.pts.p3.x + cube.pts.z.x, cube.pts.p3.y + cube.pts.z.y);
				endShape(CLOSE)
				// right: normal clr
				stroke(this.colorBr(cube.clr, 1));
				beginShape()
				vertex(cube.pts.p3.x, cube.pts.p3.y);
				vertex(cube.pts.p2.x, cube.pts.p2.y);
				vertex(cube.pts.p2.x + cube.pts.z.x, cube.pts.p2.y + cube.pts.z.y);
				vertex(cube.pts.p3.x + cube.pts.z.x, cube.pts.p3.y + cube.pts.z.y);
				endShape(CLOSE)
			}
			// top/bottom: light color
			stroke(this.colorBr(cube.clr, 1.3));
			beginShape()
			vertex(cube.pts.p1.x + cube.pts.z.x, cube.pts.p1.y + cube.pts.z.y);
			vertex(cube.pts.p2.x + cube.pts.z.x, cube.pts.p2.y + cube.pts.z.y);
			vertex(cube.pts.p3.x + cube.pts.z.x, cube.pts.p3.y + cube.pts.z.y);
			vertex(cube.pts.p4.x + cube.pts.z.x, cube.pts.p4.y + cube.pts.z.y);
			endShape(CLOSE)
		}
	}

	drawCubesOutline() {
		// this.sortCubes();

		noFill();
		fill(BG)
		for (const cube of this.cubes) {
			strokeWeight(2);

			// top/bottom: light color
			stroke(cube.clr);
			beginShape();
			vertex(cube.pts.p1.x + cube.pts.z.x, cube.pts.p1.y + cube.pts.z.y);
			vertex(cube.pts.p2.x + cube.pts.z.x, cube.pts.p2.y + cube.pts.z.y);
			vertex(cube.pts.p2.x, cube.pts.p2.y);
			vertex(cube.pts.p3.x, cube.pts.p3.y);
			vertex(cube.pts.p4.x, cube.pts.p4.y);
			vertex(cube.pts.p4.x + cube.pts.z.x, cube.pts.p4.y + cube.pts.z.y);
			endShape(CLOSE);

			if (cube.pts.z.y !== 0) {
				strokeWeight(1);

				// left: dark clr
				stroke(this.colorBr(cube.clr, 0.7));
				beginShape();
				vertex(cube.pts.p2.x + cube.pts.z.x, cube.pts.p2.y + cube.pts.z.y);
				vertex(cube.pts.p3.x + cube.pts.z.x, cube.pts.p3.y + cube.pts.z.y);
				vertex(cube.pts.p4.x + cube.pts.z.x, cube.pts.p4.y + cube.pts.z.y);
				endShape();

				line(
					cube.pts.p3.x, cube.pts.p3.y,
					cube.pts.p3.x + cube.pts.z.x, cube.pts.p3.y + cube.pts.z.y
				);
			}
		}
	}

	drawCubesSVG() {
		this.sortCubes();

		noFill();
		for (const cube of this.cubes) {
			strokeWeight(2);

			// top/bottom: light color
			stroke(32);
			beginShape();
			vertex(cube.pts.p3.x, cube.pts.p3.y);
			vertex(cube.pts.p4.x, cube.pts.p4.y);
			if (cube.pts.z.y !== 0) vertex(cube.pts.p4.x + cube.pts.z.x, cube.pts.p4.y + cube.pts.z.y);
			vertex(cube.pts.p1.x + cube.pts.z.x, cube.pts.p1.y + cube.pts.z.y);
			if (cube.pts.z.y !== 0) vertex(cube.pts.p2.x + cube.pts.z.x, cube.pts.p2.y + cube.pts.z.y);
			vertex(cube.pts.p2.x, cube.pts.p2.y);
			vertex(cube.pts.p3.x, cube.pts.p3.y);
			if (cube.pts.z.y !== 0) vertex(cube.pts.p3.x + cube.pts.z.x, cube.pts.p3.y + cube.pts.z.y);
			endShape();

			if (cube.pts.z.y !== 0) {
				strokeWeight(1);
				beginShape();
				vertex(cube.pts.p2.x + cube.pts.z.x, cube.pts.p2.y + cube.pts.z.y);
				vertex(cube.pts.p3.x + cube.pts.z.x, cube.pts.p3.y + cube.pts.z.y);
				vertex(cube.pts.p4.x + cube.pts.z.x, cube.pts.p4.y + cube.pts.z.y);
				endShape();
			}
		}
	}

	colorBr(clr, br = 1) {
		let clrR = red(window.color(clr));
		let clrG = green(window.color(clr));
		let clrB = blue(window.color(clr));
		let clrA = alpha(window.color(clr));

		clrR = constrain(clrR * br, 0, 255);
		clrG = constrain(clrG * br, 0, 255);
		clrB = constrain(clrB * br, 0, 255);

		return color(clrR, clrG, clrB, clrA);
	}

}

