/*
	iso cyber cubes #genuary5 #genuary #genuary2505
	Layers upon layers upon layers
	https://openprocessing.org/sketch/2500515
	#generativeart #creativecoding #p5js
*/

let iso;
const USE_SVG = false;
const NUM = 12;
let SCL = 20;
const CLRS = ["purple", "cyan", "darkred", "darkorange", "orange", "white"];
const BG = "#02020C";

function setup() {
	if (USE_SVG) {
		createCanvas(500, 800, SVG);
		SCL = 10;
	} else {
		createCanvas(windowWidth, windowHeight);
		describe("iso cyber cubes");
	}
	strokeJoin(BEVEL);
	noStroke()

	iso = new ISO(~~(width / 2), ~~(height * 0.6), SCL);

	const pad = { x: P = 0.2, y: P, z: 0 }; // P=map((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), 0, width, 0, 0.4)
	var dim = { w: 10, h: 10 };
	shuffle(CLRS, true);
	for (let i = 0; i < NUM; i++) {
		var x = ~~random(dim.w - 1);
		const y = ~~randomGaussian(map(i, 0, NUM-1, 0, dim.h-1)); // ~~random(dim.h - 1);
		const z = ~~abs(randomGaussian(0, 10));
		const w = ~~random(1, max(1, dim.w - x));
		const h = ~~random(1, max(1, dim.h - y));
		const clr = color(CLRS[i % CLRS.length]);
		iso.addCube(
			{ x, y, z }, 
			{ x: w, y: h, z: ~~random(1, 5) }, 
			clr, pad
		); // noise(2234+frameCount/51) 
		// console.log(`x ${x}, y ${y}, w ${w}, h ${h}`)
	}
	// console.log(iso.cubes)

	loop();
}

function draw() {
	if (!USE_SVG) background(BG);

	stroke(!USE_SVG ? "silver" : 32);
	iso.drawCoordSystem(15);

	if (USE_SVG) {
		iso.drawCubesSVG();
	} else {
		iso.drawCubesOutline(); // drawCubes()
	}

	if (!USE_SVG) drawMsg("Iso Cyber Cubes (epi) #genuary2505");
	// noLoop() removed for animation
}

function drawMsg(msg) {
	push();

	fill("black")
	noStroke();
	textAlign(LEFT, TOP)
	text(msg, 1, 1)

	fill("white")
	noStroke();
	textAlign(LEFT, TOP)
	text(msg, 0, 0)

	pop();
}

function mousePressed() {
	if (mouseButton !== RIGHT) setup();
}

function keyPressed() {
	if (key === 's' || key === 'S') {
		save("epi_iso_cubes.svg"); // Save the canvas as SVG
	}
}
